/* no lambdas: a "stage" is a loop plus a function pointer with a void* payload */
typedef void (*stage_fn)(const Row *row, void *ctx);

static void run_stage(const Row *rows, size_t n, stage_fn f, void *ctx) {
    for (size_t i = 0; i < n; ++i)
        f(&rows[i], ctx);          /* map/filter fused by hand */
}

int by_name(const void *a, const void *b);   /* stdlib callback, no closure */
qsort(rows, n, sizeof *rows, by_name);
